/* 功能中心：校内生活示例与公开赛事、考试入口。 */
window.createCampusFeatures = function(ctx) {
  'use strict';
  const {school,esc,icon,heading,footer,showModal,closeModal,navigate,renderPage,toast,ensureAuth,isAuthenticated,currentCourses,state,persist,isPinned=()=>false}=ctx;
  const key='xueyu-features-demo-v1';
  let stored={}; try {stored=JSON.parse(localStorage.getItem(key)||'{}')||{};} catch {}
  const data={saved:Array.isArray(stored.saved)?stored.saved.filter(x=>typeof x==='string'):[],items:Array.isArray(stored.items)?stored.items.filter(x=>x&&typeof x.id==='string'&&typeof x.school==='string'&&typeof x.title==='string'&&typeof x.price==='number'&&Number.isFinite(x.price)&&x.price>=0&&typeof x.description==='string'&&typeof x.category==='string'&&typeof x.place==='string'):[]};
  const ui={category:'全部',query:'',savedOnly:false};
  const routeStates=new Map();
  const directory={category:'all',query:''};
  let lastRoute='',lastSchool=school().id;
  const titles={jobs:'校园兼职',marketplace:'二手交易',competitions:'竞赛活动',exams:'语言与资格考试',finals:'校内期末考试'};
  const categories={jobs:['全部','校内助理','技能兼职','短期活动'],marketplace:['全部','书籍资料','数码设备','运动生活'],competitions:['全部','编程科技','数学建模','校内活动'],exams:['全部','语言考试','职业资格']};
  const tint={jobs:'peach',marketplace:'sage',competitions:'lilac',exams:'blue',finals:'sand'};
  function save(){try{localStorage.setItem(key,JSON.stringify(data));}catch{toast('当前浏览器无法保存，暂存于本页。');}}
  const saved=id=>data.saved.includes(id);
  const meta=(type,id,fields)=>({type,id:`${school().id}-${type}-${id}`,...fields});
  function jobs(){return [
    meta('jobs','library',{title:'图书馆 · 阅读空间助理',category:'校内助理',org:'图书馆学生服务组（示例）',price:'¥20 / 小时',time:'每周 2 次 · 课余排班',place:'本校图书馆',description:'协助图书整理、阅读区引导与活动布置。可提前沟通课表安排，具体工作时段由双方确认。',requirements:'认真细致，愿意参与校园公共服务。',contact:'study'}),
    meta('jobs','design',{title:school().id==='qinghe'?'校园活动海报设计':'校园活动网页制作',category:'技能兼职',org:'校园创意工作室（示例）',price:'¥150 / 项目起',time:'按项目沟通 · 时间灵活',place:'线上沟通 / 校内',description:'为校内活动提供创意支持，先沟通需求与交付内容，再决定是否接单。',requirements:'有相关作品，能够清晰表达自己的设计或开发思路。',contact:'music'}),
    meta('jobs','event',{title:'周末校园市集 · 活动协助',category:'短期活动',org:'校园生活服务组（示例）',price:'¥100 / 天',time:'周末白天 · 示例岗位',place:'本校学生活动中心',description:'协助布置摊位、指引路线与整理物料。岗位信息、薪酬均为演示，不接受真实应聘。',requirements:'善于沟通，报名后与负责人确认工作时段。',contact:'volunteer'})];}
  function items(){return [...data.items.filter(x=>x.school===school().id).map(x=>({...x,type:'marketplace'})),
    meta('marketplace','book',{title:school().id==='qinghe'?'设计基础书籍 · 三本打包':'数据结构与算法教材',category:'书籍资料',price:28,condition:'少量笔记',place:'图书馆门口',description:'书籍保存完整，少量学习笔记，适合新学期继续使用。图片为分类插画，商品为虚构示例。',seller:'苏同学',contact:'study'}),
    meta('marketplace','keyboard',{title:'无线键盘 · 奶油白',category:'数码设备',price:65,condition:'九成新',place:'学生活动中心',description:'日常学习用键盘，配件齐全。仅展示二手交易流程，没有实际商品或支付功能。',seller:'周同学',contact:'music'}),
    meta('marketplace','sport',{title:'羽毛球拍 · 带拍套',category:'运动生活',price:40,condition:'正常使用痕迹',place:'体育馆门口',description:'适合课余运动的入门球拍。可在聊天中交流物品情况，再约定校内当面检查。',seller:'晓禾',contact:'volunteer'})];}
  function competitions(){return [
    meta('competitions','lanqiao',{title:'蓝桥杯',subtitle:'软件与信息技术竞赛',category:'编程科技',symbol:'</>',description:'了解当届赛道、报名通知和竞赛安排，选择与你学习方向相符的项目。',url:'https://dasai.lanqiao.cn/',source:'蓝桥杯大赛官网',steps:['查看当届赛道与参赛要求','关注本校竞赛组织通知','按当届通知完成报名与备赛']}),
    meta('competitions','modeling',{title:'全国大学生数学建模竞赛',subtitle:'把数学带入真实问题',category:'数学建模',symbol:'∑',description:'查阅竞赛通知、章程和历年赛题，提前规划学习与组队。',url:'https://www.mcm.edu.cn/',source:'全国大学生数学建模竞赛官网',steps:['阅读当届竞赛章程','通过本校通知了解组队与报名方式','准备建模、编程和论文表达']}),
    meta('competitions','campus',{title:school().id==='qinghe'?'校园创意设计交流会':'校园算法与建模交流会',subtitle:'寻找一起进步的伙伴',category:'校内活动',symbol:'✳',description:'本校示例交流活动，可在校园论坛分享学习方向与组队想法。具体时间和地点待校方发布。',source:school().shortName+'学术活动（示例）',steps:['关注学院后续公告','整理自己的学习方向','在校园论坛交流组队想法']})];}
  function exams(){return [
    meta('exams','cet',{title:'英语四六级',subtitle:'CET-4 / CET-6',category:'语言考试',symbol:'Aa',description:'集中查看大学英语四、六级考试的官方动态、报名入口和成绩服务。',url:'https://cet.neea.edu.cn/',source:'中国教育考试网 · CET',steps:['核对本校报名资格与通知','留意笔试、口试分别安排','按官方通知查看准考证与成绩']}),
    meta('exams','ielts',{title:'雅思',subtitle:'IELTS',category:'语言考试',symbol:'I',description:'通过官方入口了解考试类型、考点与可选场次，按个人计划安排备考。',url:'https://ielts.neea.cn/',source:'教育部教育考试院 · 雅思报名',steps:['确认适用的考试类型','在官方平台查询考点与场次','阅读费用、改期及考试当天要求']}),
    meta('exams','psc',{title:'普通话水平测试',subtitle:'PSC',category:'语言考试',symbol:'言',description:'查看所在地测试站信息与报名安排，场次、名额和要求以测试机构公告为准。',url:'https://bm.cltt.org/',source:'国家普通话水平测试在线报名系统',steps:['选择所在地区与测试站','阅读测试站报名须知','核对测试安排与证件要求']}),
    meta('exams','ntce',{title:'教师资格考试',subtitle:'中小学教师资格考试 · NTCE',category:'职业资格',symbol:'教',description:'通过官方入口查看考试动态、报考流程及成绩信息。报考条件以当地当次公告为准。',url:'https://ntce.neea.edu.cn/',source:'中国教育考试网 · NTCE',steps:['核对所在省份报考公告','分别关注笔试与面试安排','按官方要求完成报名与材料核验']})];}
  const all=()=>[...jobs(),...items(),...competitions(),...exams()];
  const find=id=>all().find(x=>x.id===id);
  const group=type=>({jobs,marketplace:items,competitions,exams}[type]?.()||[]);
  const routeBtn=(route,title,kind='secondary')=>`<button class="${kind}-btn" data-route="${route}">${title}${icon('arrow')}</button>`;
  function entry(){return `<button class="feature-entry" data-route="features"><span class="feature-entry-icon">${icon('compass')}</span><span><strong>功能中心</strong><small>兼职 · 闲置 · 竞赛 · 考试，发现校园的更多可能</small></span>${icon('arrow')}</button>`;}
  const services=[
    {id:'schedule',group:'study',icon:'calendar',title:'我的课表',description:'导入课表，安排一周节奏',keywords:'教务 课程 导入'},
    {id:'grades',group:'study',icon:'graduation',title:'成绩查询',description:'了解本学期的学习进度',action:true,keywords:'教务 学分'},
    {id:'finals',group:'study',icon:'file',title:'校内期末考试',description:'本校课程考试的独立安排',keywords:'考试 考场 教务'},
    {id:'competitions',group:'study',icon:'graduation',title:'竞赛活动',description:'蓝桥杯、建模与校内交流',keywords:'比赛 蓝桥杯 数学 建模'},
    {id:'exams',group:'study',icon:'book',title:'语言与资格考试',description:'四六级、雅思、普通话、教资',keywords:'考试 CET IELTS 证书'},
    {id:'ai',group:'study',icon:'sparkle',title:'AI 工作区',description:'校园问答与 AI 学堂',keywords:'模型 API 学习 讲义 视频'},
    {id:'map',group:'life',icon:'map',title:'校园地图',description:'找到教室，也发现校园角落',keywords:'卡通 地点 路线 导航'},
    {id:'library',group:'life',icon:'book',title:'图书借阅',description:'借阅记录与续借服务',action:true,keywords:'图书馆 书籍 到期'},
    {id:'campus-card',group:'life',icon:'card',title:'校园一卡通',description:'查看自己的校园卡信息',action:true,keywords:'余额 卡片'},
    {id:'repair',group:'life',icon:'wrench',title:'校园报修',description:'让生活里的小问题被看见',action:true,keywords:'宿舍 维修'},
    {id:'bus',group:'life',icon:'bus',title:'校车时刻',description:'提前安排下一段校内行程',action:true,keywords:'公交 出行 交通'},
    {id:'guides',group:'life',icon:'compass',title:'生活指南',description:'办事地点、流程与校园问答',keywords:'新生 办事 食堂 自习'},
    {id:'jobs',group:'life',icon:'card',title:'校园兼职',description:'先了解岗位，再决定投入',keywords:'工作 实践 助理 项目'},
    {id:'marketplace',group:'life',icon:'leaf',title:'二手交易',description:'让闲置在同学手中继续发光',keywords:'买卖 闲置 书籍 数码 运动'}
  ];
  function serviceMatches(){const q=directory.query.trim().toLowerCase();return services.filter(s=>(directory.category==='all'||s.group===directory.category)&&(!q||`${s.title} ${s.description} ${s.keywords}`.toLowerCase().includes(q)));}
  function directoryResults(){const rows=serviceMatches();return `<div class="service-results-meta" role="status" aria-live="polite"><span>${directory.query?'搜索结果':directory.category==='study'?'学习成长':directory.category==='life'?'校园生活':'全部服务'}</span><span>${rows.length} 项服务</span></div>${rows.length?`<div class="service-grid">${rows.map(s=>`<article class="service-tile service-${s.group} ${s.id==='ai'?'service-ai':''}"><button class="service-tile-main" ${s.action?'data-action':'data-route'}="${s.id}"><span class="service-symbol">${icon(s.icon)}</span><span class="service-copy"><strong>${s.title}</strong><small>${s.description}</small></span><span class="service-open">${icon('arrow')}</span></button><button class="service-pin" data-action="pin-service" data-id="${s.id}" aria-label="${isPinned(s.id)?s.title+'已加入原桌面':'将'+s.title+'加入原自定义桌面'}" ${isPinned(s.id)?'disabled':''}>${icon(isPinned(s.id)?'check':'plus')}${isPinned(s.id)?'已加入原桌面':'加入原桌面'}</button></article>`).join('')}</div>`:`<div class="service-empty">${icon('search')}<h2>没有找到这项服务</h2><p>试试课表、考试或图书，也可以切换分类。</p><button class="secondary-btn" data-action="service-clear">清除筛选</button></div>`}`;}
  function hub(){return `${heading('CAMPUS TOOLKIT','需要什么，就从这里出发。','学习与生活的服务，各有自己的位置。')}<div class="service-directory"><div class="service-search-row"><label class="service-search">${icon('search')}<input id="service-search" type="search" value="${esc(directory.query)}" placeholder="找课表、地图、考试或生活服务" aria-label="搜索校园服务"/></label><span class="service-campus">${icon('school')}${esc(school().shortName)}</span></div><div class="service-group-tabs" aria-label="服务分组">${[['all','全部'],['study','学习成长'],['life','校园生活']].map(([id,title])=>`<button data-action="service-group" data-id="${id}" aria-pressed="${directory.category===id}" class="${directory.category===id?'selected':''}">${title}</button>`).join('')}</div><div id="service-results">${directoryResults()}</div></div><div class="service-layout-link"><span>${icon('settings')}习惯，也可以自己安排。</span><button class="text-link" data-route="service-layout">我的服务布局${icon('chevron')}</button></div><p class="feature-disclaimer">功能数据为演示。选择的服务会作为快捷入口加入本校原自定义桌面，继续打开同一个主页面。</p>${footer()}`;}
  function filtered(type){return group(type).filter(x=>(ui.category==='全部'||x.category===ui.category)&&(!ui.savedOnly||saved(x.id))&&`${x.title} ${x.description} ${x.org||''}`.toLowerCase().includes(ui.query.toLowerCase()));}
  function card(x){const market=x.type==='marketplace',job=x.type==='jobs',education=!market&&!job;return `<article class="feature-card ${tint[x.type]}">${market?`<button class="feature-item-art ${x.category==='数码设备'?'blue':x.category==='运动生活'?'peach':'sage'}" data-action="feature-detail" data-id="${esc(x.id)}" aria-label="查看${esc(x.title)}">${icon(x.category==='数码设备'?'card':x.category==='运动生活'?'run':'book')}<span>${esc(x.condition||'学生闲置')}</span></button>`:''}<div class="feature-card-content"><div class="feature-card-meta"><span class="feature-badge">${esc(x.category)}</span>${x.mine?'<span>我发布的</span>':education?(x.url?'<span>官方资讯入口</span>':'<span>本校示例活动</span>'):'<span>演示信息</span>'}</div>${education?`<div class="feature-education-symbol" aria-hidden="true">${esc(x.symbol)}</div>`:''}<h2><button data-action="feature-detail" data-id="${esc(x.id)}">${esc(x.title)}</button></h2>${education?`<p class="feature-subtitle">${esc(x.subtitle)}</p>`:''}<p class="feature-description">${esc(education?x.description:job?x.org:x.description)}</p>${job?`<p class="feature-line">${icon('clock')}${esc(x.time)}</p><p class="feature-line">${icon('pin')}${esc(x.place)}</p>`:''}${education?`<p class="feature-line">${icon('clock')}时间与报名以官方公告为准</p>`:''}<div class="feature-card-bottom">${job||market?`<strong class="feature-price">${market?'¥'+esc(x.price):esc(x.price)}</strong>`:`<small>${x.url?'查看官方公告':'本校示例 · 待发布'}</small>`}<button class="feature-save ${saved(x.id)?'selected':''}" data-action="feature-save" data-id="${esc(x.id)}" aria-label="${saved(x.id)?'取消收藏':'收藏'}${esc(x.title)}" aria-pressed="${saved(x.id)}">${icon('bookmark')}</button></div><button class="feature-detail-link" data-action="feature-detail" data-id="${esc(x.id)}">${market?'查看物品':job?'了解岗位':'查看资讯'}${icon('arrow')}</button>${x.sold?'<div class="feature-sold">已下架</div>':''}</div></article>`;}
  function results(type){const rows=filtered(type);return rows.length?`<div class="feature-list-grid ${type==='marketplace'?'market-grid':''}">${rows.map(card).join('')}</div>`:`<div class="feature-empty">${icon('search')}<h2>这里暂时没有匹配的信息</h2><p>换一个关键词、分类，或取消仅看收藏。</p></div>`;}
  function listing(type){const desc={jobs:'寻找适合课余时间的机会，先了解，再沟通。',marketplace:'让好物在校园里继续发光，支持发布你的闲置。',competitions:'从兴趣出发，找到下一场值得投入的挑战。',exams:'语言与资格考试集中查看，与本校期末考试分开。'};return `${heading('CAMPUS SERVICES',titles[type],desc[type],type==='marketplace'?`<button class="primary-btn" data-action="feature-publish">${icon('plus')}发布闲置</button>`:'')}${type==='exams'?`<div class="feature-scope-note">${icon('file')}<div><strong>语言与资格考试</strong><p>收录四六级、雅思、普通话和教师资格考试；本校课程期末安排独立归入校内期末考试。</p></div></div>`:`<p class="feature-mini-note">${icon('school')}${esc(school().name)} · ${type==='competitions'?'公开赛事入口与本校示例活动':'本校生活服务演示'}${type==='jobs'?' · 岗位与薪酬均为虚构示例':''}</p>`}<div class="feature-controls"><div class="filters">${categories[type].map(c=>`<button class="filter-btn ${ui.category===c?'active':''}" data-action="feature-category" data-id="${c}" aria-pressed="${ui.category===c}">${c}</button>`).join('')}</div><div class="feature-search-row"><label class="inline-search">${icon('search')}<input id="feature-search" type="search" aria-label="搜索${titles[type]}" placeholder="搜索${titles[type]}" value="${esc(ui.query)}"/></label><button class="secondary-btn ${ui.savedOnly?'is-selected':''}" data-action="feature-saved-only" aria-pressed="${ui.savedOnly}">${icon('bookmark')}${ui.savedOnly?'查看全部':'仅看收藏'}</button></div></div><div id="feature-results">${results(type)}</div><p class="feature-disclaimer">${type==='jobs'||type==='marketplace'?'本演示只在当前浏览器保存，联系会进入同校演示私信；没有真实应聘、交易或支付。':'资讯卡用于演示分类与收藏；官方入口为外部网站，具体安排、资格和费用以当届公告为准。'}</p>${footer()}`;}
  function detail(id){const x=find(id);if(!x)return;const education=x.type==='competitions'||x.type==='exams';showModal(`<div class="modal-content"><span class="modal-tag">${esc(titles[x.type])} · ${esc(x.category)}</span><h2>${esc(x.title)}</h2><p class="modal-intro">${esc(x.subtitle||x.org||'同校闲置 · '+(x.seller||'林同学'))}</p><div class="detail-body">${esc(x.description)}</div>${education?`<div class="feature-detail-status">${icon('clock')}报名与考试 / 比赛日期：请查看官方当届公告</div><ol class="guide-steps">${x.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="form-note">来源：${esc(x.source)}${x.url?' · 官方入口核对于 2026-10-25':' · 演示活动'}</p>`:`<div class="auth-profile"><p><span>${x.type==='jobs'?'示例薪酬':'物品价格'}</span><strong>${x.type==='jobs'?esc(x.price):'¥'+esc(x.price)}</strong></p><p><span>${x.type==='jobs'?'时间安排':'物品情况'}</span><strong>${esc(x.time||x.condition||'以描述为准')}</strong></p><p><span>地点</span><strong>${esc(x.place)}</strong></p>${x.requirements?`<p><span>岗位要求</span><strong>${esc(x.requirements)}</strong></p>`:''}</div><p class="form-note">${x.mine?'这是你在本浏览器发布的闲置，可手动下架。':'示例人物与信息，仅供体验流程。联系后进入演示私信，不会通知真实用户。'}</p>`}<div class="feature-detail-actions"><button class="secondary-btn" data-action="feature-save" data-id="${esc(id)}" data-detail="true">${icon('bookmark')}${saved(id)?'已收藏':'收藏信息'}</button>${education?(x.url?`<a class="primary-btn" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">查看官方公告${icon('link')}</a>`:routeBtn('forum','去论坛交流','primary')):x.mine?`<button class="primary-btn" data-action="feature-toggle-sold" data-id="${esc(id)}">${x.sold?'重新上架':'下架物品'}</button>`:x.sold?'<span class="feature-badge">已下架</span>':`<button class="primary-btn" data-action="community-thread" data-id="${school().id}-contact-${esc(x.contact)}">${icon('message')}${x.type==='jobs'?'联系岗位方（演示）':'联系卖家（演示）'}</button>`}</div></div>`);}
  function publish(){showModal(`<div class="modal-content"><span class="modal-tag">${esc(school().name)} · 二手交易</span><h2>给闲置一个新去处。</h2><p class="modal-intro">信息仅保存在你的当前浏览器，用于演示发布流程。</p><form id="feature-publish-form" data-school="${school().id}"><label class="form-label" for="item-title">物品名称</label><input id="item-title" class="form-input" name="title" maxlength="48" required placeholder="例如：九成新台灯"/><div class="feature-form-pair"><div><label class="form-label" for="item-category">物品分类</label><select id="item-category" class="form-input" name="category">${categories.marketplace.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></div><div><label class="form-label" for="item-price">价格（元）</label><input id="item-price" class="form-input" name="price" type="number" min="0" max="99999" step="0.01" required placeholder="0.00"/></div></div><label class="form-label" for="item-place">校内交接地点</label><input id="item-place" class="form-input" name="place" maxlength="48" required placeholder="例如：图书馆门口"/><label class="form-label" for="item-description">物品描述</label><textarea id="item-description" class="form-input" name="description" rows="4" maxlength="600" required placeholder="写下新旧程度、配件和使用情况"></textarea><p class="form-error" id="feature-form-error" role="alert"></p><button class="primary-btn full-btn" type="submit">发布到本校闲置 ${icon('arrow')}</button></form></div>`);}
  function finals(){const courses=[...new Map(currentCourses().map(c=>[c.name,c])).values()];return `${heading('ACADEMIC AFFAIRS / FINAL EXAMS','校内期末考试','只展示当前学校、本学期课程的考试安排。')}<div class="feature-scope-note finals">${icon('school')}<div><strong>${esc(school().name)} · 2026–2027 学年第一学期</strong><p>本校课程的教务考试区，与语言、资格考试分别管理。</p></div></div>${isAuthenticated()?`<section class="feature-finals-status">${icon('calendar')}<h2>等待教务发布考试安排</h2><p>尚未接入学校教务考试接口。下方仅列出当前课表课程，考试时间、地点与形式均待确认。</p><span>当前课表：${state.imports[school().id]?'本地导入':'示例课表'} · ${courses.length} 门课程</span></section><div class="feature-finals-list">${courses.map(c=>`<article><span class="feature-tile-icon sand">${icon('book')}</span><div><h3>${esc(c.name)}</h3><p>任课教师：${esc(c.teacher)} · 考核方式待教务确认</p></div><span class="feature-pending">时间 / 考场待公布</span></article>`).join('')}</div>`:`<div class="feature-empty">${icon('shield')}<h2>先认证，查看自己的课程考试区</h2><p>使用预填示例学号即可体验；本演示没有真实教务考试安排。</p><button class="primary-btn" data-action="feature-finals-login">体验学号认证</button></div>`}<p class="feature-disclaimer">正式版本需由学校授权对接考试安排；当前不会生成虚构考试日期或考场。</p>${footer()}`;}
  function rememberRoute(){if(lastRoute)routeStates.set(lastSchool+':'+lastRoute,{...ui});}
  function schoolChanged(){rememberRoute();Object.assign(ui,{category:'全部',query:'',savedOnly:false});lastRoute='';lastSchool=school().id;directory.category='all';directory.query='';}
  function routePage(type){if(lastRoute!==type||lastSchool!==school().id){rememberRoute();lastRoute=type;lastSchool=school().id;Object.assign(ui,routeStates.get(lastSchool+':'+type)||{category:'全部',query:'',savedOnly:false});}return listing(type);}
  const actions={
    'service-group':id=>{if(!['all','study','life'].includes(id))return;directory.category=id;renderPage();},
    'service-clear':()=>{directory.category='all';directory.query='';renderPage();},
    'feature-detail':detail,
    'feature-category':c=>{if(categories[state.route]?.includes(c)){ui.category=c;renderPage();}},
    'feature-saved-only':()=>{ui.savedOnly=!ui.savedOnly;renderPage();},
    'feature-save':(id,el)=>{if(!find(id))return;const index=data.saved.indexOf(id);if(index<0)data.saved.push(id);else data.saved.splice(index,1);save();renderPage();if(el?.dataset.detail)detail(id);toast(index<0?'已加入我的收藏':'已取消收藏');},
    'feature-publish':()=>{const id=school().id;ensureAuth(()=>{if(school().id===id)publish();else toast('学校已切换，请在当前学校重新发布。');});},
    'feature-toggle-sold':id=>{const x=data.items.find(x=>x.id===id&&x.school===school().id);if(!x)return;ensureAuth(()=>{if(x.school!==school().id)return;x.sold=!x.sold;save();renderPage();detail(id);toast(x.sold?'物品已下架':'物品已重新上架');});},
    'feature-finals-login':()=>ensureAuth(()=>navigate('finals'))
  };
  function onSubmit(e){const f=e.target;if(f.id!=='feature-publish-form')return;e.preventDefault();if(f.dataset.school!==school().id||!isAuthenticated()){closeModal();toast('校园身份已变化，请重新发布。');return;}const v=new FormData(f),title=String(v.get('title')||'').trim(),price=Number(v.get('price')),place=String(v.get('place')||'').trim(),description=String(v.get('description')||'').trim(),category=String(v.get('category'));if(!title||!place||!description||!Number.isFinite(price)||price<0||price>99999||!categories.marketplace.includes(category)){document.querySelector('#feature-form-error').textContent='请完整填写物品信息及有效价格。';return;}data.items.unshift({id:school().id+'-marketplace-own-'+crypto.randomUUID(),school:school().id,title:title.slice(0,48),price,place:place.slice(0,48),description:description.slice(0,600),category,mine:true,seller:'林同学',condition:'查看描述',sold:false});save();schoolChanged();routeStates.set(school().id+':marketplace',{category:'全部',query:'',savedOnly:false});closeModal();navigate('marketplace');toast('闲置已在本浏览器发布');}
  function onInput(e){if(e.target.id==='service-search'){directory.query=e.target.value;const root=document.querySelector('#service-results');if(root)root.innerHTML=directoryResults();return;}if(e.target.id!=='feature-search')return;ui.query=e.target.value;const root=document.querySelector('#feature-results');if(root)root.innerHTML=results(state.route);}
  const searchGroups=()=>Object.entries(titles).filter(([type])=>type!=='finals').map(([type,title])=>[title,type==='competitions'?'graduation':type==='exams'?'file':type==='jobs'?'card':'book',group(type).map(x=>({...x,name:x.title,desc:x.category+' · '+(x.subtitle||x.org||x.description),kind:'feature-detail'}))]);
  const savedItems=()=>all().filter(x=>saved(x.id));
  const ownedItems=()=>items().filter(x=>x.mine);
  return {entry,searchGroups,savedItems,ownedItems,widgetItems:group,pages:{features:hub,jobs:()=>routePage('jobs'),marketplace:()=>routePage('marketplace'),competitions:()=>routePage('competitions'),exams:()=>routePage('exams'),finals},actions,onInput,onSubmit,schoolChanged};
};
